// 1. Pega o texto bruto do CSV vindo do nó HTTP Request
const csvText = $input.first().json.data;

if (!csvText) {
  return [];
}

// 2. Divide o texto em linhas, removendo quebras vazias
const linhas = csvText.trim().split(/\r?\n/);

if (linhas.length < 2) {
  return [];
}

// 3. Extrai e limpa os cabeçalhos (primeira linha do CSV)
const headers = linhas[0].split(',').map(h => h.trim());

// 4. Mapeia cada linha subsequente em um objeto formatado para o n8n
const itensFormatados = linhas.slice(1).map(linha => {
  const valores = linha.split(',').map(v => v.trim());
  const obj = {};

  headers.forEach((header, index) => {
    let valor = valores[index] !== undefined ? valores[index] : '';

    // Converte opcionalmente a coluna 'minimo' para número para facilitar regras futuras
    if (header.toLowerCase() === 'minimo') {
      valor = Number(valor) || valor;
    }

    obj[header] = valor;
  });

  // Retorna no formato de item padrão do n8n
  return { json: obj };
});

return itensFormatados;

// 1. Pega a lista de clientes (do Webhook)
const clientes = $('Webhook').first().json.body.clientes;

// 2. Pega a lista de investimentos formatada pelo nó de código anterior
const investimentos = $('Code in JavaScript').all().map(item => item.json);

// Função auxiliar para extrair o valor numérico da rentabilidade e ordenar do maior para o menor
function extrairRentabilidadeNumerica(rentabilidadeStr) {
  if (!rentabilidadeStr || rentabilidadeStr.toLowerCase().includes('variável')) {
    return 0; // Atribui 0 ou prioridade menor para opções de renda variável
  }
  const matches = rentabilidadeStr.match(/[\d,\.]+/g);
  if (matches && matches.length > 0) {
    const numStr = matches[matches.length - 1].replace(/\./g, '').replace(',', '.');
    return parseFloat(numStr) || 0;
  }
  return 0;
}

// 3. Itera sobre cada cliente para encontrar APENAS A MELHOR opção compatível
const resultado = clientes.map(cliente => {
  // Trata e converte o saldo do cliente (ex: "R$ 12.500,00" -> 12500)
  let saldoNumerico = 0;
  if (typeof cliente.saldo === 'number') {
    saldoNumerico = cliente.saldo;
  } else if (typeof cliente.saldo === 'string') {
    saldoNumerico = parseFloat(
      cliente.saldo.replace('R$', '').replace(/\./g, '').replace(',', '.').trim()
    ) || 0;
  }

  // Filtra as opções que atendem ao perfil e cujo mínimo cabe no saldo
  const opcoesElegiveis = investimentos.filter(inv => {
    const mesmoPerfil = inv.perfil.toLowerCase() === cliente.perfil.toLowerCase();

    const minimoNumerico = parseFloat(
      String(inv.minimo).replace('R$', '').replace(/\./g, '').replace(',', '.').trim()
    ) || 0;

    const saldoSuficiente = saldoNumerico >= minimoNumerico;

    return mesmoPerfil && saldoSuficiente;
  });

  // Ordena as opções elegíveis da MAIOR rentabilidade para a menor
  opcoesElegiveis.sort((a, b) => {
    return extrairRentabilidadeNumerica(b.rentabilidade) - extrairRentabilidadeNumerica(a.rentabilidade);
  });

  // Pega apenas a melhor opção (a primeira da lista após a ordenação)
  const melhorOpcao = opcoesElegiveis.length > 0 ? opcoesElegiveis[0] : null;

  // Monta a linha de exibição da melhor opção
  let textoInvestimento = '';
  if (melhorOpcao) {
    textoInvestimento = `• ${melhorOpcao.produto} (Aplicação Mínima: R$ ${melhorOpcao.minimo} | Rentabilidade: ${melhorOpcao.rentabilidade})`;
  } else {
    textoInvestimento = '• No momento, não encontramos nenhuma opção com valor mínimo compatível com o seu saldo atual.';
  }

  // Monta a mensagem final personalizada destacando a recomendação única
  const mensagem = `Olá, ${cliente.nome}!\n\n` +
    `Identificamos que seu perfil de investidor é *${cliente.perfil}* e seu saldo disponível é de *${cliente.saldo}*.\n\n` +
    `Com base nisso, selecionamos a **melhor opção de investimento** ideal para o seu momento:\n` +
    `${textoInvestimento}\n\n` +
    `Se precisar de suporte para realizar a aplicação, estamos à disposição!`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      mensagemPersonalizada: mensagem,
      melhorInvestimento: melhorOpcao
    }
  };
});

return resultado;

