return $input.all().map(item => {
  try {
    // 1. Acessa o texto bruto gerado pelo modelo
    let rawText = item.json.content.parts[0].text;

    // 2. Remove as marcações de bloco de código do Markdown (```json e ```)
    rawText = rawText.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();

    // 3. Converte a string JSON limpa em um objeto JavaScript real
    const parsedData = JSON.parse(rawText);

    // 4. Retorna os dados normalizados para o n8n
    return {
      json: parsedData
    };
  } catch (error) {
    // Retorno de segurança caso ocorra algum erro no parse
    return {
      json: {
        erro: "Falha ao normalizar o texto para JSON",
        textoOriginal: item.json.content.parts[0].text
      }
    };
  }
});
